import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import WalletCard from "../components/WalletCard";
import WalletService from "../services/WalletService";
import { useAuth } from "../context/AuthContext";
import "./WalletPage.css";

export default function WalletPage() {
  const { isGuest } = useAuth();
  const navigate = useNavigate();
  const [wallet, setWallet] = useState(null);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(null); // 'topup' | 'pay' | null
  const [amount, setAmount] = useState("");
  const [label, setLabel] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (isGuest) {
      setLoading(false);
      return;
    }
    WalletService.getWallet().then((w) => {
      setWallet(w);
      setLoading(false);
    });
  }, [isGuest]);

  function closeModal() {
    setModal(null);
    setAmount("");
    setLabel("");
    setError("");
  }

  async function confirmModal() {
    const value = parseFloat(amount);
    if (!value || value <= 0) {
      setError("Enter an amount greater than 0.");
      return;
    }
    setBusy(true);
    setError("");
    try {
      const updated =
        modal === "topup"
          ? await WalletService.addFunds(value)
          : await WalletService.pay(value, label || "Simulated payment");
      setWallet(updated);
      closeModal();
    } catch (err) {
      setError("Something went wrong — please try again.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      <Navbar />
      <div className="page-shell">
        <h3 className="section-title">Wallet</h3>

        {isGuest ? (
          <div className="card-lock">
            The campus wallet is only available to signed-in students.
            <div style={{ marginTop: 14 }}>
              <button className="btn btn-primary btn-sm" onClick={() => navigate("/login")}>Sign in</button>
            </div>
          </div>
        ) : loading ? (
          <p className="muted">Loading wallet ...</p>
        ) : (
          <>
            <WalletCard
              balance={wallet.balance}
              currency={wallet.currency}
              onAddFunds={() => setModal("topup")}
              onPay={() => setModal("pay")}
            />

            <h3 className="section-title">Recent activity</h3>
            <div className="tx-list">
              {wallet.transactions.map((t) => (
                <div className="tx-item" key={t.id}>
                  <div>
                    <div className="tx-label">{t.label}</div>
                    <div className="tx-date">{t.date}</div>
                  </div>
                  <div className={`tx-amount ${t.amount >= 0 ? "positive" : "negative"}`}>
                    {t.amount >= 0 ? "+" : ""}{t.amount.toFixed(2)}
                  </div>
                </div>
              ))}
            </div>
          </>
        )}

        {modal && (
          <div className="wallet-modal-backdrop" onClick={closeModal}>
            <div className="wallet-modal" onClick={(e) => e.stopPropagation()}>
              <h4>{modal === "topup" ? "Add funds" : "Simulate a payment"}</h4>
              {error && <div className="error-banner">{error}</div>}
              <input
                className="field"
                type="number"
                min="0"
                step="0.01"
                placeholder="Amount (ZAR)"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
              />
              {modal === "pay" && (
                <input
                  className="field"
                  placeholder="What's this for? (optional)"
                  value={label}
                  onChange={(e) => setLabel(e.target.value)}
                />
              )}
              <div className="wallet-modal-actions">
                <button className="btn btn-ghost btn-sm" onClick={closeModal}>Cancel</button>
                <button className="btn btn-primary btn-sm" onClick={confirmModal} disabled={busy}>
                  {busy ? "Working ..." : "Confirm"}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
